			if (chunk.type === 'Text') {
				return escapeTemplate(escape(chunk.data).replace(/"/g, '&quot;'));
			}

			block.contextualise(chunk.expression);
			const { snippet } = chunk.metadata;
			return '${__escape(' + snippet + ')}';
		})
		.join('');
